using System.Drawing;using System.Drawing.Drawing2D;using System.Reflection;using System.Runtime.CompilerServices;using System.Windows.Forms;
namespace AngraQaIntegration;
/// <summary>Read-only guidance. Reuses the approved PET Coach overlay and vector glow through reflection.</summary>
public static class EmployeeTutorial {
 static bool observing;static readonly ConditionalWeakTable<Form,Button> buttons=new();
 public static readonly string[] Steps={"Proprietário: abra FUNCIONÁRIOS / PROPRIETÁRIO. Configure 001 somente se ainda não estiver ativo. Use sua senha apenas na página segura.","Na administração, informe a matrícula fixa (002 em diante), nome completo e perfil. Funcionário não cria a própria matrícula.","Marque as permissões desejadas para funcionário ou gerente. Só o proprietário pode conceder ou retirar opções.","Após cadastrar, guarde o código individual de ativação em segurança. É de uso único e vale 24 horas. Não o envie ao chat.","No celular do funcionário, conecte ao PDV e abra PRIMEIRO ACESSO / ATIVAR. Informe matrícula e código e crie a própria senha.","Perdeu o código? Na administração, localize a pessoa e use REEMITIR ATIVAÇÃO. O código anterior deixa de funcionar; senha e sessões anteriores são revogadas.","Para revisar opções use ALTERAR PERFIL / PERMISSÕES. Para suspender use BLOQUEAR; para retirar o acesso use EXCLUIR ACESSO. Os dados comerciais permanecem."};
 public static void Observe(){if(observing)return;observing=true;Application.Idle+=Scan;Scan(null,EventArgs.Empty);}
 static IEnumerable<Control> All(Control root){yield return root;foreach(Control c in root.Controls)foreach(var x in All(c))yield return x;}
 static void Scan(object? s,EventArgs e){foreach(Form form in Application.OpenForms.Cast<Form>().ToArray())if(form.GetType().FullName=="LealInfoPDV.GlassWorkshopForm"&&form.GetType().Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().Any(x=>x.Key=="PetIdentity"&&x.Value=="005"))Attach(form);}
 public static void Attach(Form form){if(buttons.TryGetValue(form,out _))return;var target=All(form).FirstOrDefault(c=>c.Name=="AngraOwnerAdministration"||c.Name=="AngraIntegration");if(target==null)return;var button=new Button{Name="AngraEmployeeTutorial",Text="COMO CADASTRAR FUNCIONÁRIOS",AutoSize=true,MinimumSize=new Size(240,44),AccessibleName="Como cadastrar funcionários"};
 if(target.Parent is FlowLayoutPanel flow){flow.Controls.Add(button);flow.Controls.SetChildIndex(button,Math.Min(flow.Controls.GetChildIndex(target)+1,flow.Controls.Count-1));}else{button.Dock=DockStyle.Bottom;form.Controls.Add(button);button.BringToFront();}buttons.Add(form,button);button.Click+=(_,_)=>new Guide(form,target).Show(form);}
 public sealed class Guide:Form {
  readonly Form owner;readonly Control target;readonly TextBox text=new(){Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BorderStyle=BorderStyle.None,BackColor=Color.FromArgb(8,18,36),ForeColor=Color.White,AccessibleName="Instrução do tutorial"};readonly Label state=new(){AutoSize=true,MaximumSize=new Size(380,0)};readonly System.Windows.Forms.Timer timer=new(){Interval=80};readonly FlowLayoutPanel nav=new(){Dock=DockStyle.Bottom,AutoSize=true,WrapContents=true};
  int step;Form? overlay;MethodInfo? render;Action<Graphics,GraphicsPath,Color,float,float>? glow;bool closing;public int Step=>step;
  public Guide(Form owner,Control target){this.owner=owner;this.target=target;Name="AngraEmployeeGuide";Text="Como cadastrar funcionários • somente orientação";AutoScaleMode=AutoScaleMode.Dpi;StartPosition=FormStartPosition.Manual;FormBorderStyle=FormBorderStyle.SizableToolWindow;ShowInTaskbar=false;MinimumSize=new Size(280,300);Size=new Size(410,390);Font=new Font("Segoe UI",11);BackColor=Color.FromArgb(8,18,36);ForeColor=Color.White;var area=Screen.FromControl(owner).WorkingArea;Location=new Point(Math.Max(area.Left,area.Right-Width-12),Math.Max(area.Top,area.Bottom-Height-12));Controls.Add(text);Controls.Add(nav);Add("VOLTAR",()=>MoveStep(-1));Add("PRÓXIMO",()=>MoveStep(1));Add("VER NOVAMENTE",Restart);Add("SAIR",Close);timer.Tick+=(_,_)=>Draw();FormClosed+=(_,_)=>Cleanup();owner.FormClosed+=OwnerClosed;UpdateText();timer.Start();}
  void Add(string caption,Action click){var b=new Button{Text=caption,AutoSize=true,AccessibleName=caption};b.Click+=(_,_)=>click();nav.Controls.Add(b);}
  public void MoveStep(int delta){step=Math.Clamp(step+delta,0,Steps.Length-1);UpdateText();}public void Restart(){step=0;UpdateText();}
  void UpdateText(){text.Text=$"{step+1} de {Steps.Length}\n\n{Steps[step]}\n\n"+(step>1?"Esta etapa acontece no navegador ou no APK. O destaque segue apenas controles visíveis do PDV; nenhuma conta ou código é criado pelo tutorial.":"Use o controle destacado para abrir a administração. Você pode operar o PDV normalmente.");nav.Controls[0].Enabled=step>0;nav.Controls[1].Enabled=step<Steps.Length-1;}
  void OwnerClosed(object? s,FormClosedEventArgs e)=>Close();
  bool Resolve(){if(overlay!=null)return true;var coach=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("AngraHelpPremium.Coach",false)).FirstOrDefault(t=>t!=null);if(coach==null){var pet=owner.GetType().Assembly;using var helper=pet.GetManifestResourceStream("ANGRA.HelpPremium.Helper");if(helper!=null)try{coach=System.Runtime.Loader.AssemblyLoadContext.Default.LoadFromStream(helper).GetType("AngraHelpPremium.Coach",false);}catch{}}if(coach==null)return false;var type=coach.GetNestedType("Overlay",BindingFlags.NonPublic);var glowMethod=coach.GetMethod("Glow",BindingFlags.Static|BindingFlags.NonPublic);if(type==null||glowMethod==null)return false;overlay=(Form)Activator.CreateInstance(type,true)!;overlay.Name="AngraEmployeeTutorialHighlight";render=type.GetMethod("Render",BindingFlags.Public|BindingFlags.Instance);glow=glowMethod.CreateDelegate<Action<Graphics,GraphicsPath,Color,float,float>>();return render!=null;}
  void Draw(){if(closing||owner.IsDisposed||target.IsDisposed)return;if(step>1||!owner.Visible||owner.WindowState==FormWindowState.Minimized||!target.Visible){overlay?.Hide();return;}try{if(!Resolve())return;var area=Rectangle.Intersect(owner.RectangleToScreen(owner.ClientRectangle),Screen.FromControl(owner).WorkingArea);var bounds=target.RectangleToScreen(target.ClientRectangle);if(!area.Contains(bounds)||area.Width<1||area.Height<1){overlay?.Hide();return;}float scale=Math.Max(.75f,owner.DeviceDpi/96f);render!.Invoke(overlay,new object[]{area,(Action<Graphics>)(g=>{g.SmoothingMode=SmoothingMode.AntiAlias;var ring=bounds;ring.Offset(-area.X,-area.Y);ring.Inflate((int)(8*scale),(int)(6*scale));using(var shade=new SolidBrush(Color.FromArgb(28,0,0,0))){using var mask=new GraphicsPath(FillMode.Alternate);mask.AddRectangle(new Rectangle(Point.Empty,area.Size));mask.AddEllipse(ring);g.FillPath(shade,mask);}using var circle=new GraphicsPath();circle.AddEllipse(ring);glow!(g,circle,Color.FromArgb(255,62,70),3*scale,1);using var arrow=new GraphicsPath();float x=ring.Left+ring.Width/2f,y=ring.Bottom+4*scale,tail=Math.Min(area.Height-8,y+45*scale);arrow.AddLine(x,tail,x,y);arrow.AddLine(x,y,x-9*scale,y+12*scale);arrow.StartFigure();arrow.AddLine(x,y,x+9*scale,y+12*scale);glow(g,arrow,Color.FromArgb(0,218,255),3*scale,1);})});if(!overlay!.Visible)overlay.Show(owner);}catch{overlay?.Hide();}}
  void Cleanup(){if(closing)return;closing=true;timer.Stop();timer.Dispose();owner.FormClosed-=OwnerClosed;overlay?.Close();overlay?.Dispose();overlay=null;}
  protected override void Dispose(bool disposing){if(disposing)Cleanup();base.Dispose(disposing);}
 }
}
